use crate::aap::caps::{http_client, state_read};

struct Node;

fn percent_encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // Enrichment lookup. The result is deliberately discarded (including
        // transport failures), so the node's output is unchanged.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&info.date)
        );
        let _ = http_client::fetch(&url);

        let raw = state_read::get("urls").unwrap_or_default();
        let urls = raw
            .lines()
            .map(|l| l.trim())
            .filter(|l| !l.is_empty())
            .map(|l| l.to_string())
            .collect();

        SubscriptionList { urls }
    }
}

export!(Node);
```

Two assumptions to check:
- **Enrichment query:** `run-info` has no text field, so I used `info.date`, percent-encoded, as the `q` value.
- **Store key:** the spec doesn't name the key in the `subscriptions` store, so I read `"urls"` as newline-separated URLs.

The enrichment response and any fetch error are discarded, so the output depends only on the state read.

